import java.util.*;
import java.util.stream.Collectors;

public final class Solution {
    public static List<String> patchConfig(Map<String, String> base, List<String[]> patches) {
        if (patches == null || patches.isEmpty()) {
            return new ArrayList<>(base.values());
        }
        List<String> result = new ArrayList<>(base.values());
        for (String[] p : patches) {
            if (p == null || p.length < 2) {
                continue;
            }
            String op = p[0];
            if (!op.equals("set") && !op.equals("unset")) {
                continue;
            }
            String key = p[1];
            if (key == null || key.isEmpty()) {
                continue;
            }
            if (!base.containsKey(key)) {
                if (op.equals("unset")) {
                    result.remove(key);
                }
            } else {
                if (op.equals("set")) {
                    result.set(result.indexOf(key), String.format("%s=%s", key, p[2]));
                } else {
                    result.remove(result.indexOf(key));
                }
            }
        }
        return result.stream()
                .sorted((a, b) -> a.compareTo(b))
                .collect(Collectors.toList());
    }
}

